class ChecklistItem:
    def __init__(self, description, completed=False):
        self.description = description
        self.completed = completed

# Define a class to represent a Personalized Checklist/Itinerary
class PersonalChecklist:
    def __init__(self, title):
        self.title = title
        self.items = []

    def add_item(self, item):
        self.items.append(item)

    def complete_item(self, description):
        for item in self.items:
            if item.description == description:
                item.completed = True
                break

    def save_to_file(self, filename):
        with open(filename, 'w') as file:
            data = {
                'title': self.title,
                'items': [{'description': item.description, 'completed': item.completed} for item in self.items]
            }
            json.dump(data, file)

    @staticmethod
    def load_from_file(filename):
        with open(filename, 'r') as file:
            data = json.load(file)
            checklist = PersonalChecklist(data['title'])
            for item_data in data['items']:
                item = ChecklistItem(item_data['description'], item_data['completed'])
                checklist.add_item(item)
            return checklist
```
This code defines two classes: `ChecklistItem` and `PersonalChecklist`. The `ChecklistItem` class represents a single item on the checklist, which has a description and a completion status. The `PersonalChecklist` class represents the overall checklist/itinerary, which contains a list of items and provides methods to add items, mark items as completed, and save/load the checklist from a JSON file.

