from pywavefront import Wavefront

class ModelViewer(pyglet.window.Window):
    def __init__(self, *args, **kwargs):
        super(ModelViewer, self).__init__(*args, **kwargs)
        self.model = None
        self.scale = 1.0
        self.rotation_x = 0.0
        self.rotation_y = 0.0

    def load_model(self, filepath):
        wf = Wavefront(filepath, collect_faces=True)
        vertices = wf.vertices
        normals = wf.normals
        faces = wf.meshes[0].faces
        vlist = []
        for face in faces:
            for i in range(3):
                vlist.extend(vertices[face[i]])
                if normals:
                    vlist.extend(normals[face[i]])
        vertex_list = (pyglet.graphics.vertexdomain.VertexList(len(faces) * 3, 'v3f/n3f', ('t2f', [0]*len(vlist))))
        for i in range(len(faces) * 3):
            vertex_list[i*6:(i+1)*6] = vlist[i*9:i*9+6]
            if normals:
                vertex_list[i*6+3:i*6+6] = vlist[i*9+6:]
        self.model = vertex_list

    def on_draw(self):
        glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT)
        glEnable(GL_CULL_FACE)
        glLoadIdentity()
        glTranslatef(0, 0, -5)
        glRotatef(self.rotation_x, 1, 0, 0)
        glRotatef(self.rotation_y, 0, 1, 0)
        glScalef(self.scale, self.scale, self.scale)
        if self.model:
            self.model.draw(GL_TRIANGLES)

    def on_key_press(self, symbol, modifiers):
        if symbol == pyglet.window.key.SPACE:
            self.scale *= 1.1
        elif symbol == pyglet.window.key.SHIFT_L:
            self.scale /= 1.1
        elif symbol == pyglet.window.key.UP:
            self.rotation_x += 5
        elif symbol == pyglet.window.key.DOWN:
            self.rotation_x -= 5
        elif symbol == pyglet.window.key.LEFT:
            self.rotation_y += 5
        elif symbol == pyglet.window.key.RIGHT:
            self.rotation_y -= 5

if __name__ == "__main__":
    window = ModelViewer(width=800, height=600, caption='Model Viewer')
    window.load_model('path/to/your/model.obj')  # Replace with your model file path
    pyglet.app.run()
```
