import subprocess

class ArchiveInterface:
    def __init__(self, binary_path):
        self.binary_path = binary_path

    def extract(self, archive_path, destination_path=None):
        if not destination_path:
            destination_path = './'

        command = [self.binary_path, 'x', '-o' + destination_path, archive_path]
        try:
