import io

app = Flask(__name__)

def modify_image(image):
    # Example modification: convert image to grayscale
    return image.convert('L')

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return jsonify({"error": "No file part"}), 400

    file = request.files['file']

    if file.filename == '':
        return jsonify({"error": "No selected file"}), 400

    if file:
        try:
            img = Image.open(file)
            modified_img = modify_image(img)

            buffered = io.BytesIO()
            modified_img.save(buffered, format="JPEG")
            img_byte_arr = buffered.getvalue()

            return jsonify({"status": "success", "image_data": img_byte_arr.decode('utf-8')}), 200

        except Exception as e:
            return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
```

